ter_id=~\\"$cluster_id\\"}))","labels":["svc","svc_name","service","service_name"]},{"name":"related_nodes","label":"相关节点","type":"label","value":".*","multi":true,"required":false,"defaultValue":".*","includeAll":true,"allValue":".*","query":"query_result( group by (node_name) (container_memory_rss{job_name=\\"integrations/kubernetes/cadvisor\\",pod=~\\"$pod\\",pod!=\\"\\", cluster_id=~\\"$cluster_id\\"}) or group by (node_name) ( kindling_span_trace_duration_nanoseconds_count{svc_name=\\"$service_name\\",svc_name!=\\"\\", cluster_id=~\\"$cluster_id\\"}))","labels":["node_name"]},{"name":"resolution","label":"精度","type":"custom","value":"1m","multi":false,"required":false,"defaultValue":"1m","options":[{"label":"1s","value":"1s"},{"label":"15s","value":"15s"},{"label":"30s","value":"30s"},{"label":"1m","value":"1m"},{"label":"3m","value":"3m"},{"label":"5m","value":"5m"},{"label":"10m","value":"10m"},{"label":"30m","value":"30m"}],"query":"1s, 15s, 30s, 1m, 3m, 5m , 10m, 30m"},{"name":"related_pid","label":"关联进程 ID","type":"label","value":".*","multi":true,"required":false,"defaultValue":".*","includeAll":true,"allValue":".*","query":"label_values(kindling_span_trace_duration_nanoseconds_count{svc_name=~\\"$service_name\\", cluster_id=~\\"$cluster_id\\"},pid)","labels":["pid"]},{"name":"jvm_instance","label":"JVM实例","type":"label","value":".*","multi":true,"required":false,"defaultValue":".*","includeAll":true,"allValue":".*","query":"query_result(jvm_cpu_count{host_name=~\\"$pod\\", cluster_id=~\\"$cluster_id\\"} or jvm_cpu_count{service_name=~\\"$service_name\\",vm=\\"$service_type\\", cluster_id=~\\"$cluster_id\\"})","labels":["instance"]},{"name":"job_name","label":"采集任务","type":"label","value":"","multi":false,"required":false,"defaultValue":"","query":"label_values(node_cpu_seconds_total,job_name)","labels":["job_name"]},{"name":"cadvisor_job_name","label":"容器采集任务","type":"label","value":"","multi":false,"required":false,"defaultValue":"","query":"label_value