  'everyone',
  '[]',
  '{"id":"","name":"宿主机监控指标","description":"从 Grafana 面板迁移并汉化，已转换为“我的面板”原生格式。来源：node-exporter。","ownerId":0,"creator":"","visibility":"everyone","teamIds":[],"variables":[{"name":"cluster_id","label":"集群","type":"cluster","value":".*","multi":true,"required":false,"defaultValue":".*","includeAll":true,"allValue":".*","query":"SELECT DISTINCT scope_id AS __value, \\nCASE \\n  WHEN c.name != '''' THEN c.name\\n  ELSE scope_id\\nEND AS __text\\nFROM data_scope \\nLEFT JOIN clusters c ON scope_id  = c.id\\nWHERE type = ''cluster''","labels":["cluster","cluster_id","clusterId","clusterID","cluster_name"]},{"name":"job","label":"采集任务","type":"label","value":"","multi":false,"required":false,"defaultValue":"","query":"label_values(node_uname_info,job_name)","labels":["job_name"]},{"name":"node","label":"主机","type":"label","value":"","multi":false,"required":false,"defaultValue":"","query":"label_values(node_uname_info{job_name=\\"$job\\", cluster_id=~\\"$cluster_id\\"},instance_name)","labels":["instance_name"]}],"widgets":[{"id":"grafana-323","title":"资源压力","description":"资源压力。","type":"barGauge","layout":{"x":0,"y":0,"w":1,"h":1},"query":{"mode":"custom","presetId":"","expression":"irate(node_pressure_cpu_waiting_seconds_total{instance_name=\\"$node\\",job_name=\\"$job\\", cluster_id=~\\"${cluster_id:regex}\\"}[$__rate_interval])","params":{},"legend":"CPU 指标","queries":[{"id":"CPU some","expression":"irate(node_pressure_cpu_waiting_seconds_total{instance_name=\\"$node\\",job_name=\\"$job\\", cluster_id=~\\"${cluster_id:regex}\\"}[$__rate_interval])","legend":"CPU 指标"},{"id":"Memory some","expression":"irate(node_pressure_memory_waiting_seconds_total{instance_name=\\"$node\\",job_name=\\"$job\\", cluster_id=~\\"${cluster_id:regex}\\"}[$__rate_interval])","legend":"内存指标"},{"id":"I/O some","expression":"irate(node_pressure_io_waiting_seconds_total{instance_name=\\"$node\\",job_name=\\"$job\\", cluster_id=~\\"${cluster_id:regex}\\"}[$__rate_interval])","legend":"I/O 指标"}]},