-- thread-polaris-vm: 线程级北极星指标（虚拟机）
INSERT INTO custom_dashboard
  (id, name, description, owner_id, visibility, team_ids, config, created_at, updated_at)
SELECT
  'f5de1a3a-f2fb-58ed-b4a7-4790313e9daa',
  '线程级北极星指标（虚拟机）',
  '从 Grafana 面板迁移并汉化，已转换为“我的面板”原生格式。来源：thread-polaris-vm。',
  (SELECT user_id FROM "user" WHERE username = 'admin' LIMIT 1),
  'everyone',
  '[]',
  '{"id":"","name":"线程级北极星指标（虚拟机）","description":"从 Grafana 面板迁移并汉化，已转换为“我的面板”原生格式。来源：thread-polaris-vm。","ownerId":0,"creator":"","visibility":"everyone","teamIds":[],"variables":[{"name":"cluster_id","label":"集群","type":"cluster","value":".*","multi":true,"required":false,"defaultValue":".*","includeAll":true,"allValue":".*","query":"SELECT DISTINCT scope_id AS __value, \\nCASE \\n  WHEN c.name != '''' THEN c.name\\n  ELSE scope_id\\nEND AS __text\\nFROM data_scope \\nLEFT JOIN clusters c ON scope_id  = c.id\\nWHERE type = ''cluster''","labels":["cluster","cluster_id","clusterId","clusterID","cluster_name"]},{"name":"node","label":"主机","type":"label","value":"node-56","multi":false,"required":false,"defaultValue":"node-56","query":"label_values(originx_thread_polaris_nanoseconds_count{type=\\"cpu\\", cluster_id=~\\"$cluster_id\\"},node_name)","labels":["node_name"]},{"name":"pid","label":"进程 ID","type":"label","value":"24743","multi":false,"required":false,"defaultValue":"24743","query":"label_values(originx_thread_polaris_nanoseconds_count{type=\\"cpu\\", node_name=\\"$node\\",cluster_id=~\\"$cluster_id\\"},pid)","labels":["pid"]},{"name":"tid","label":"线程","type":"label","value":".*","multi":true,"required":false,"defaultValue":".*","includeAll":true,"allValue":".*","query":"label_values(originx_thread_polaris_nanoseconds_count{pid=~\\"$pid\\", cluster_id=~\\"$cluster_id\\"},tid_key)","labels":["tid_key"]},{"name":"interval","label":"采样间隔","type":"custom","value":"1m","multi":false,"required":false,"defaultValue":"1m","options":[{"label":"15s","value":"15s"},{"label":"30s","value":"30s"},{"label":"1m","value":"1m"},{"label":"5m","value":"5m"},{"label":"10m","value":"10m"},{"label":"30m","value":"30m"},{"label":"1h","value":"1h"},{"label":"6h","value":"6h"},{"label":"12h","value":"12h"},{"label":"1d","value":"1d"},{"label":"7d","value":"7d"}],"query":"15s,30s,1m,5m,10m,30m,1h,6h,12h,1d,7d"},{"name":"job","label":"采集任务","type":"label","value":"integrations/process