SELECT
  'aa78fb07-aad0-5d46-aca2-89b9835bd067',
  'Kafka 指标',
  '从 Grafana 面板迁移并汉化，已转换为“我的面板”原生格式。来源：kafka。',
  (SELECT user_id FROM "user" WHERE username = 'admin' LIMIT 1),
  'everyone',
